-- Fotos ilustrativas para os tipos de comida novos (Wikimedia Commons, uso livre com crédito).
-- Escolhidas olhando cada uma em 14/11/2026.
UPDATE cuisines c SET photo_url = v.url, photo_credit = v.credit, photo_credit_url = v.page,
  photo_width = v.w, photo_height = v.h
FROM (VALUES
  ('hamburgueria', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/cf/Cheeseburger_with_onions_at_Hatfield_Heath_Festival_2017.jpg/1280px-Cheeseburger_with_onions_at_Hatfield_Heath_Festival_2017.jpg', 'Foto ilustrativa: Acabashi · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3ACheeseburger_with_onions_at_Hatfield_Heath_Festival_2017.jpg', 1280, 1280),
  ('churrascaria', 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/Churrasco_carioca.jpg/1280px-Churrasco_carioca.jpg', 'Foto ilustrativa: Leonardo "Leguas" Carvalho · CC BY-SA 2.5 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AChurrasco_carioca.jpg', 1280, 851),
  ('doceria', 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/Brigadeiros.jpg/1280px-Brigadeiros.jpg', 'Foto ilustrativa: Rodrigogomesonetwo · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3ABrigadeiros.jpg', 1280, 1707),
  ('chinesa', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/2019-02-22_Xiaolongbao_in_%22Taste_Of_Shanghai%22_restaurant%2C_Sydney%2C_Australia.jpg/1280px-2019-02-22_Xiaolongbao_in_%22Taste_Of_Shanghai%22_restaurant%2C_Sydney%2C_Australia.jpg', 'Foto ilustrativa: Maksym Kozlenko · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3A2019-02-22_Xiaolongbao_in_%22Taste_Of_Shanghai%22_restaurant%2C_Sydney%2C_Australia.jpg', 1280, 960),
  ('coreana', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Beef_Bibimbap_-_SAERO_2025-11-06.jpg/1280px-Beef_Bibimbap_-_SAERO_2025-11-06.jpg', 'Foto ilustrativa: Andy Li · CC0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3ABeef_Bibimbap_-_SAERO_2025-11-06.jpg', 1280, 964),
  ('peruana', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1b/Ceviche_de_pescado_%28La_Punta%2C_Callao%29.jpg/1280px-Ceviche_de_pescado_%28La_Punta%2C_Callao%29.jpg', 'Foto ilustrativa: Jorge G. Mori · domínio público · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3ACeviche_de_pescado_%28La_Punta%2C_Callao%29.jpg', 1280, 960),
  ('padaria', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c3/Ch%C3%A1_mate_e_p%C3%A3o_na_chapa_com_queijo_minas.jpg/1280px-Ch%C3%A1_mate_e_p%C3%A3o_na_chapa_com_queijo_minas.jpg', 'Foto ilustrativa: Sintegrity · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3ACh%C3%A1_mate_e_p%C3%A3o_na_chapa_com_queijo_minas.jpg', 1280, 1707),
