  ('indiana', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/46/Darjeeling%2C_India%2C_Indian_Thali_meal.jpg/1280px-Darjeeling%2C_India%2C_Indian_Thali_meal.jpg', 'Foto ilustrativa: Vyacheslav Argenberg · CC BY 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3ADarjeeling%2C_India%2C_Indian_Thali_meal.jpg', 1280, 853),
  ('mexicana', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d1/%28El_Flaco%29_Al_Pastor_Tacos.jpg/1280px-%28El_Flaco%29_Al_Pastor_Tacos.jpg', 'Foto ilustrativa: City Foodsters · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3A%28El_Flaco%29_Al_Pastor_Tacos.jpg', 1280, 853),
  ('frutos-do-mar', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/6b/Moqueca.jpg/1280px-Moqueca.jpg', 'Foto ilustrativa: BR · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AMoqueca.jpg', 1280, 853)
